    g.bonds.forEach(b => { adj.get(b.a).push({ id: b.b, order: b.order }); adj.get(b.b).push({ id: b.a, order: b.order }); });
    const atomOf = id => g.atoms.find(a => a.id === id);
    const bsym = o => (o === 2 ? '=' : o === 3 ? '#' : '');
    const key = (a, b) => (a < b ? a + '_' + b : b + '_' + a);

    // pass 1 — find ring-closure (back) edges
