        const pick = (c, other) => adj.get(c).find(nb => nb.id !== other && nb.order === 1 && treeEdges.has(key(c, nb.id)));
        const ra = pick(db.a, db.b), rb = pick(db.b, db.a);
        if (!ra || !rb) return;
        const X = atomOf(ra.id), Y = atomOf(rb.id);
        const ex = B.x - A.x, ey = B.y - A.y;
        const sideX = Math.sign(ex * (X.y - A.y) - ey * (X.x - A.x)), sideY = Math.sign(ex * (Y.y - B.y) - ey * (Y.x - B.x));
        if (!sideX || !sideY) return;
        const dbKey = key(db.a, db.b);
        const add = (k, rec) => { if (!ezRef.has(k)) ezRef.set(k, []); ezRef.get(k).push(rec); };
        add(key(db.a, ra.id), { dbKey, centre: db.a });
        add(key(db.b, rb.id), { dbKey, centre: db.b });
