      const kids = adj.get(id).filter(nb => treeEdges.has(key(id, nb.id)) && !written.has(nb.id));

      // does this centre have a configuration we can express?
      const canon = canonicalStereoOrder(g, id);
      const parity = isStereocenter(g, a) ? stereoParity(g, id) : null;
      const hasStereo = parity !== null && canon.length === 4;

      // the order this string will list the neighbours in — @/@@ is defined against it
      const emitOrder = [];
      if (parent !== null && parent !== undefined) emitOrder.push({ kind: 'atom', id: parent });
      if (hasStereo && implicitH(g, a) === 1) emitOrder.push({ kind: 'H' });
      ringP.forEach(pid => emitOrder.push({ kind: 'atom', id: pid }));
      kids.forEach(nb => emitOrder.push({ kind: 'atom', id: nb.id }));

      let stereoTok = '';
