    const wa = winner(A.id, B.id), wb = winner(B.id, A.id);
    if (!wa || !wb || wa === 'tie' || wb === 'tie') return null;
    const ux = B.x - A.x, uy = B.y - A.y;
    const side = p => Math.sign(ux * (p.y - A.y) - uy * (p.x - A.x));
    const sa = side(wa), sb = side(wb);
    if (!sa || !sb) return null;                           // drawn collinear
