  const MOL_LIBRARY = MOL_LIBRARY_RAW.split('\n').map(line => {
    const [n, s, k, f, t, a, cas] = line.split('|');
    return { name: n, smiles: s, key: k, formula: f,
             tags: t ? t.split(',') : [], alt: a ? a.split(';') : [], cas: cas || null };
  });
  const MOL_BY_NAME = new Map();
  const MOL_BY_KEY = new Map();
  const MOL_ENTRY_BY_KEY = new Map();
  const MOL_ENTRIES_BY_KEY = new Map();
  const MOL_BY_CAS = new Map();
  MOL_LIBRARY.forEach(e => {
    MOL_BY_NAME.set(e.name.toLowerCase(), e);
    e.alt.forEach(a => { if (!MOL_BY_NAME.has(a.toLowerCase())) MOL_BY_NAME.set(a.toLowerCase(), e); });
    if (e.key && !MOL_BY_KEY.has(e.key)) { MOL_BY_KEY.set(e.key, e.name); MOL_ENTRY_BY_KEY.set(e.key, e); }
    /* canonicalKey is deliberately stereo-BLIND (reactions and retrosynthesis want to match
       skeletons), so one key can hold two stereoisomers — fumaric and maleic acid, geraniol and
       nerol, angelic and tiglic acid. Keep them all and let the lookup pick by geometry. */
    if (e.key) { if (!MOL_ENTRIES_BY_KEY.has(e.key)) MOL_ENTRIES_BY_KEY.set(e.key, []); MOL_ENTRIES_BY_KEY.get(e.key).push(e); }
    if (e.cas && !MOL_BY_CAS.has(e.cas)) MOL_BY_CAS.set(e.cas, e);
  });

  /* ---- CAS Registry Numbers ----
     A CAS number is an ASSIGNED registry label (like a phone number), not a
     code you can compute from the structure — so the app carries an embedded
     table, matched offline by structure (InChIKey) against a public registry
     dataset of ~76,500 substances. 3,186 of the library's molecules have one;
     every embedded number passes the CAS check-digit test. For anything
     critical, verify at commonchemistry.cas.org. */
  function casChecksumOk(cas) {
    const m = String(cas).trim().match(/^(\d{2,7})-(\d{2})-(\d)$/);
    if (!m) return false;
    const digits = (m[1] + m[2]).split('').reverse();
    const sum = digits.reduce((acc, d, i) => acc + (i + 1) * (+d), 0);
    return sum % 10 === +m[3];
  }
  function looksLikeCAS(str) {
    return /^\d{2,7}-\d{2}-\d$/.test(String(str).trim());
  }
