    'aspirin': 'CC(=O)OC1=CC=CC=C1C(=O)O',
    'acetylsalicylic acid': 'CC(=O)OC1=CC=CC=C1C(=O)O',
    'ibuprofen': 'CC(C)CC1=CC=C(C=C1)C(C)C(=O)O',
    'acetaminophen': 'CC(=O)NC1=CC=C(O)C=C1', 'paracetamol': 'CC(=O)NC1=CC=C(O)C=C1',
