    'adrenaline': 'CNCC(O)C1=CC=C(O)C(O)=C1', 'epinephrine': 'CNCC(O)C1=CC=C(O)C(O)=C1',
    'dopamine': 'NCCC1=CC=C(O)C(O)=C1', 'serotonin': 'NCCC1=CNC2=CC=C(O)C=C12',
    'atp': 'C1=NC(=C2C(=N1)N(C=N2)C3C(C(C(O3)COP(=O)(O)OP(=O)(O)OP(=O)(O)O)O)O)N',
    'alanine': 'CC(N)C(=O)O', 'glycine': 'NCC(=O)O', 'valine': 'CC(C)C(N)C(=O)O',
    'leucine': 'CC(C)CC(N)C(=O)O', 'serine': 'OCC(N)C(=O)O', 'cysteine': 'SCC(N)C(=O)O',
