    '1-methoxybuta-1,3-diene': 'COC=CC=C', '2-methoxybuta-1,3-diene': 'C=C(OC)C=C',
    '1-methoxy-1,3-butadiene': 'COC=CC=C', '2-methoxy-1,3-butadiene': 'C=C(OC)C=C',
    'bicyclo[2.2.1]heptane': 'C1CC2CCC1C2', 'bicyclo[2.2.1]hept-2-ene': 'C1C2C=CC1CC2',
    'bicyclo[2.2.2]octane': 'C1CC2CCC1CC2', 'bicyclo[2.2.2]oct-2-ene': 'C1CC2CCC1C=C2',
    'bicyclo[2.2.1]hepta-2,5-diene': 'C1C2C=CC1C=C2',
    /* the dienes and dienophiles the course actually uses, by the names it uses */
    'nitroethylene': 'C=C[N+](=O)[O-]', 'nitroethene': 'C=C[N+](=O)[O-]',
    'cyclopentadiene': 'C1=CCC=C1', '1,3-cyclopentadiene': 'C1=CCC=C1', 'cyclopenta-1,3-diene': 'C1=CCC=C1',
