    'benzoquinone': 'O=C1C=CC(=O)C=C1', '1,4-benzoquinone': 'O=C1C=CC(=O)C=C1', 'p-benzoquinone': 'O=C1C=CC(=O)C=C1',
    'quinone': 'O=C1C=CC(=O)C=C1',
    'tetracyanoethylene': 'N#CC(C#N)=C(C#N)C#N', 'tcne': 'N#CC(C#N)=C(C#N)C#N',
    'danishefsky diene': 'COC=CC(O[Si](C)(C)C)=C', "danishefsky's diene": 'COC=CC(O[Si](C)(C)C)=C',
    'methyl acrylate': 'C=CC(=O)OC', 'ethyl acrylate': 'C=CC(=O)OCC',
    'methyl methacrylate': 'CC(=C)C(=O)OC', 'dimethyl fumarate': 'COC(=O)/C=C/C(=O)OC',
    'dimethyl maleate': 'COC(=O)/C=C\\C(=O)OC', 'diethyl fumarate': 'CCOC(=O)/C=C/C(=O)OCC',
    'maleimide': 'O=C1C=CC(=O)N1', 'N-methylmaleimide': 'CN1C(=O)C=CC1=O',
    'sorbic acid': 'C/C=C/C=C/C(=O)O', 'myrcene': 'CC(C)=CCCC(=C)C=C',
    'formalin': 'C=O', 'menthol': 'CC(C)C1CCC(C)CC1O',
    'limonene': 'CC(=C)C1CCC(C)=CC1', 'vanillin': 'COC1=C(O)C=CC(C=O)=C1',
